	.file	"xpkBLZW_lib.s"
	.text

/*
**	xpkBLZW_lib.s -- resident module header for
**	xpkBLZW.library 3.3 "Bryan's turbo-charged LZW"
**
**	Single code hunk; "moveq #-1,d0 / rts" entry stub; packed
**	RomTag (RTF_AUTOINIT, ver 3, NT_LIBRARY); InitTable with
**	dataSize 0x28 and a word-offset FUNCTABLE (generated by
**	genfunctab.py); LibInit stores the seglist at base+36.
**
**	Hunk map of the original (offset -> contents):
**	  0x00  moveq #-1,d0 / rts    entry stub
**	  0x04  RomTag                AUTOINIT, ver 3
**	  0x1e  InitTable             dataSize 0x28
**	  0x2e  functab               -1, 10 word offsets, -1
**	  0x46  datatab               flags 6, ver 3 rev 3
**	  0x66  libname / idstr / descriptor strings
**	  0xf8  XpkInfo + XpkMode ("15 bits")
**	  0x178 LibInit               store seglist @36
**	  0x180 LibOpen/Close/Expunge/null
**	  0x1d6 XpksPackerInfo        lea descriptor 0xf8
**	  0x1dc XpksPackChunk         LZW encoder (hash chains)
**	  0x43e XpksUnpackChunk       LZW decoder (bit stack)
*/

	.globl	_start
_start:
	moveq	#-1,%d0
	rts

	.globl	_romtag
_romtag:
	.word	0x4afc
	.long	_romtag
	.long	_endmodule
	.byte	0x80			/* RTF_AUTOINIT		    */
	.byte	3			/* RT_VERSION = 3	    */
	.byte	9			/* NT_LIBRARY		    */
	.byte	0			/* RT_PRI		    */
	.long	_libname
	.long	_idstr
	.long	_inittab

	.globl	_inittab
_inittab:
	.long	0x28			/* dataSize		    */
	.long	_functab
	.long	_datatab
	.long	_LibInit

_datatab:
	.byte	0xa0,0x08		/* ln_Type = 9	    */
	.byte	0x09,0x00
	.byte	0x80,0x0a		/* ln_Name	    */
	.long	_libname
	.byte	0xa0,0x0e		/* lib_Flags = 6    */
	.byte	0x06,0x00
	.byte	0x90,0x14		/* version = 3	    */
	.word	0x0003
	.byte	0x90,0x16		/* revision = 3	    */
	.word	0x0003
	.byte	0x80,0x18		/* idstring	    */
	.long	_idstr
	.byte	0x00,0x00

_libname:
	.ascii	"xpkBLZW.library"
	.byte	0
_idstr:
	.ascii	"xpkBLZW 3.3"
	.byte	13,10,0

/*
**	LibInit -- a0 = seglist, d0 = libbase, a6 = execbase.
**	Stores the seglist at base+36 and returns the base in d0.
*/
	.globl	_LibInit
_LibInit:
	moveal	%d0,%a1
	movel	%a0,%a1@(36)		/* seglist		    */
	rts

/* ------------------------------------------------------------------ */
/* static XpkInfo descriptor (XpksPackerInfo returns its address)	    */
/* ------------------------------------------------------------------ */

	.even
	.globl	_xpkinfo
_xpkinfo:
	.word	1			/* xi_XpkInfoVersion	    */
	.word	3			/* xi_LibVersion	    */
	.word	0			/* xi_MasterVersion	    */
	.word	1			/* xi_ModesVersion	    */
	.long	_s_blzw			/* xi_Name		    */
	.long	_s_longname		/* xi_LongName		    */
	.long	_s_basedesc		/* xi_Description	    */
	.long	0x424c5a57		/* xi_ID = 'BLZW'	    */
	.long	0x8009			/* xi_Flags		    */
	.long	0x7fffffff		/* xi_MaxPkInChunk	    */
	.long	0x80			/* xi_MinPkInChunk	    */
	.long	0x20000			/* xi_DefPkInChunk	    */
	.long	_s_compressing		/* xi_PackMsg		    */
	.long	_s_decompressing	/* xi_UnpackMsg		    */
	.long	_s_compressed		/* xi_PackedMsg		    */
	.long	_s_decompressed		/* xi_UnpackedMsg	    */
	.word	0x003c			/* xi_DefMode = 60	    */
	.word	0			/* xi_Pad		    */
	.long	_s_xpkmode		/* xi_ModeDesc		    */
	.long	0,0,0,0,0,0		/* xi_Reserved		    */

/* XpkMode (42 bytes): memory fields are raw bytes here
 * (PackMemory 0x3c006 = the 384 KB hash table)		    */
_s_xpkmode:
	.long	0			/* xm_Next		    */
	.long	100			/* xm_Upto		    */
	.long	1			/* xm_Flags		    */
	.long	0x3c006			/* xm_PackMemory	    */
	.long	0x20000			/* xm_UnpackMemory	    */
	.long	0x9d			/* xm_PackSpeed = 157	    */
	.long	0x17d			/* xm_UnpackSpeed = 381	    */
	.word	0x0151			/* xm_Ratio = 337	    */
	.word	0			/* xm_ChunkSize	    */
	.ascii	"15 bits"
	.byte	0,0,0

_s_blzw:
	.ascii	"BLZW"
	.byte	0
_s_longname:
	.ascii	"Bryan's turbo-charged LZW"
	.byte	0
_s_basedesc:
	.ascii	"Fast compression and decompression"
	.byte	0
_s_compressing:
	.ascii	"Compressing"
	.byte	0
_s_decompressing:
	.ascii	"Decompressing"
	.byte	0
_s_compressed:
	.ascii	"Compressed"
	.byte	0
_s_decompressed:
	.ascii	"Decompressed"
	.byte	0
	.even
